// Monta a entrada da chamada ao Claude, já enxuta.
//
// Economia de token, que é onde o custo se repete todo mês:
//  - só as 10 melhores referências, com legenda cortada em 400 caracteres
//  - do histórico, só os títulos
//  - uma única chamada gera as 4 publicações da semana

const CORTE_LEGENDA = 400;

function lista(nome) {
  try {
    return $(nome).all().map((i) => i.json).filter((j) => j && Object.keys(j).length);
  } catch (e) {
    return [];
  }
}

const referencias = lista('Supabase: 10 melhores referências').map((r) => ({
  perfil: r.perfil,
  tipo: r.tipo,
  score: Number(r.score_engajamento || 0).toFixed(2),
  legenda: (r.legenda || '').replace(/\s+/g, ' ').slice(0, CORTE_LEGENDA),
}));

const ideias = lista('Supabase: ideias novas').map((i) => ({
  id: i.id,
  titulo: i.titulo,
  detalhe: i.descricao || undefined,
}));

const jaFeitos = lista('Supabase: histórico de temas')
  .map((p) => p.titulo_interno)
  .filter(Boolean);

return [{
  json: {
    quantidade: $('Config').first().json.publicacoes_por_semana,
    referencias,
    ideias,
    ja_feitos: jaFeitos,
  },
}];

