parameters.jsCode:
// Confere o que o Claude devolveu antes de gravar qualquer coisa.
//
// O modelo pode devolver JSON quebrado, prancha demais ou travessao. Nada
// disso pode chegar ao banco: o banco recusaria, e o fluxo morreria mais
// para a frente, com metade da semana gravada.

function semTravessao(t) {
  return String(t == null ? '' : t)
    .replace(/(\d)\s*[\u2013\u2014]\s*(\d)/g, '$1-$2')
    .replace(/\s*[\u2013\u2014]\s*/g, ', ')
    .replace(/,\s*,/g, ',')
    .replace(/\s+,/g, ',');
}

const bruto = $json.content && $json.content[0] && $json.content[0].text;
if (!bruto) throw new Error('Claude nao devolveu conteudo de texto.');

// Rede de seguranca: se vier cercado de crase ou de texto, pega o JSON.
const inicio = bruto.indexOf('{');
const fim = bruto.lastIndexOf('}');
if (inicio < 0 || fim < inicio) throw new Error('Resposta do Claude nao tem JSON: ' + bruto.slice(0, 300));

let dados;
try {
  dados = JSON.parse(bruto.slice(inicio, fim + 1));
} catch (e) {
  throw new Error('JSON invalido do Claude: ' + e.message);
}

const publicacoes = Array.isArray(dados.publicacoes) ? dados.publicacoes : [];
if (publicacoes.length === 0) throw new Error('Claude nao devolveu nenhuma publicacao.');

const idsValidos = new Set($('Montar entrada').first().json.ideias.map((i) => i.id));

const saida = publicacoes.map((p, indice) => {
  const cards = Array.isArray(p.cards) ? p.cards : [];
  // Limite do proprio Instagram para carrossel.
  if (cards.length < 2 || cards.length > 10) {
    throw new Error('Publicacao ' + (indice + 1) + ' veio com ' + cards.length + ' pranchas; o Instagram aceita de 2 a 10.');
  }

  const cardsLimpos = cards.map((c, i) => {
    if (!c || !String(c.titulo || '').trim()) {
      throw new Error('Publicacao ' + (indice + 1) + ', prancha ' + (i + 1) + ' sem titulo.');
    }
    if (!String(c.busca_foto || '').trim()) {
      throw new Error('Publicacao ' + (indice + 1) + ', prancha ' + (i + 1) + ' sem busca_foto; sem isso nao existe foto real.');
    }
    return {
      ordem: i + 1,
      tipo: c.tipo || (i === 0 ? 'capa' : 'conteudo'),
      titulo: semTravessao(c.titulo).trim(),
      corpo: semTravessao(c.corpo).trim(),
      busca_foto: String(c.busca_foto).trim(),
    };
  });

  const hashtags = (Array.isArray(p.hashtags) ? p.hashtags : [])
    .map((h) => '#' + String(h).replace(/^#+/, '').trim())
    .filter((h) => h.length > 1)
    .slice(0, 30);

  return {
    json: {
      formato: 'carrossel',
      titulo_interno: semTravessao(p.titulo_interno || cardsLimpos[0].titulo).slice(0, 200),
      legenda: semTravessao(p.legenda).slice(0, 2200),
      hashtags,
      // So aceita id de ideia que realmente veio da fila.
      ideia_id: idsValidos.has(p.ideia_id) ? p.ideia_id : null,
      cards: cardsLimpos,
      status: 'rascunho',
    },
  };
});

return saida;

// Uma linha por prancha, que é como a render-card trabalha.
const saida = [];
for (const item of items) {
  // O PostgREST devolve array mesmo inserindo um só.
  const p = Array.isArray(item.json) ? item.json[0] : item.json;
  const cards = p.cards || [];
  for (const card of cards) {
    saida.push({
      json: {
        publicacao_id: p.id,
        ordem: card.ordem,
        total: cards.length,
        card,
      },
    });
  }
}
return saida;

// Junta de volta por publicação: só passa adiante a que teve TODAS as
// pranchas renderizadas. Publicação com arte pela metade continua em
// rascunho e não aparece para aprovar.
const porPublicacao = {};

for (const item of $('Uma linha por prancha').all()) {
  const id = item.json.publicacao_id;
  porPublicacao[id] = porPublicacao[id] || { esperadas: item.json.total, feitas: 0 };
}

for (const item of items) {
  const url = item.json && item.json.url_publica;
  if (!url) continue;
  // A URL pública é {publicacao_id}/{ordem}.jpg, então dá para saber de quem é.
  const achado = url.match(/publicacoes\/([0-9a-f-]{36})\//i);
  if (achado && porPublicacao[achado[1]]) porPublicacao[achado[1]].feitas++;
}

return Object.entries(porPublicacao)
  .filter(([, c]) => c.feitas >= c.esperadas && c.esperadas > 0)
  .map(([id]) => ({ json: { id } }));
